"""Offline deterministic safety tests for FR-003 / INV-003 / SEC-001 / NFR-003.

No network, no broker, no LLM call. Every fixture uses a fixed account snapshot,
fixed quote and fixed rule version so verdicts are reproducible.

The tests deliberately treat the candidate (LLM output) as untrusted: the
trusted snapshot/rules are supplied separately through ``SafetyContext``.
"""
from __future__ import annotations

from decimal import Decimal

import pytest

from tradingagents.course.safety import (
    Action,
    HoldingsSnapshot,
    ProposalStatus,
    ReasonCode,
    RuleSet,
    SafetyContext,
    validate_proposal,
)

INSTRUMENT = "AAPL"
SNAPSHOT = HoldingsSnapshot(
    snapshot_id="snap-001",
    as_of="2026-01-02T15:00:00Z",
    currency="USD",
    cash=Decimal("1000"),
    positions={"AAPL": Decimal("5")},
    flat_declared=False,
)
RULES = RuleSet(version="v1")


def make_context(**overrides) -> SafetyContext:
    values = {
        "instrument": INSTRUMENT,
        "instrument_currency": "USD",
        "holdings_snapshot": SNAPSHOT,
        "rule_set": RULES,
        "available_rule_versions": frozenset({"v1"}),
    }
    values.update(overrides)
    return SafetyContext(**values)


def make_proposal(**overrides) -> dict:
    values = {
        "action": "buy",
        "units": 2,
        "price": "100",
        "currency": "USD",
        "holdings_snapshot": SNAPSHOT.to_dict(),
        "rule_version": "v1",
        "status": "pending",
    }
    values.update(overrides)
    return values


def verdict_for(**overrides):
    return validate_proposal(make_proposal(**overrides), context=make_context())


def assert_rejected(reason: ReasonCode, **overrides):
    verdict = verdict_for(**overrides)
    assert verdict.accepted is False
    assert verdict.reason_code is reason
    assert verdict.status is ProposalStatus.REJECTED
    return verdict


@pytest.mark.unit
def test_accepts_legal_buy():
    verdict = verdict_for(units=2, price="100")
    assert verdict.accepted is True
    assert verdict.reason_code is ReasonCode.ACCEPTED
    assert verdict.status is ProposalStatus.ACCEPTED
    assert verdict.is_noop is False
    assert verdict.snapshot_id == "snap-001"
    assert verdict.rule_version == "v1"
    assert verdict.instrument == INSTRUMENT


@pytest.mark.unit
def test_accepts_legal_sell():
    verdict = verdict_for(action="sell", units=5, price="100")
    assert verdict.accepted is True
    assert verdict.reason_code is ReasonCode.ACCEPTED
    assert verdict.is_noop is False


@pytest.mark.unit
def test_accepts_legal_hold_as_noop():
    verdict = verdict_for(action="hold", units=0, price="150")
    assert verdict.accepted is True
    assert verdict.reason_code is ReasonCode.ACCEPTED
    assert verdict.is_noop is True


@pytest.mark.unit
def test_hold_with_nonzero_units_is_rejected():
    assert_rejected(ReasonCode.HOLD_UNITS_NOT_ZERO, action="hold", units=1)


@pytest.mark.unit
def test_explicit_flat_snapshot_allows_buy():
    flat = HoldingsSnapshot(
        snapshot_id="snap-flat",
        as_of="2026-01-02T15:00:00Z",
        currency="USD",
        cash=Decimal("1000"),
        positions={},
        flat_declared=True,
    )
    context = make_context(holdings_snapshot=flat)
    verdict = validate_proposal(
        make_proposal(holdings_snapshot=flat.to_dict()), context=context
    )
    assert verdict.accepted is True
    assert verdict.reason_code is ReasonCode.ACCEPTED


@pytest.mark.unit
def test_empty_holdings_without_flat_declaration_is_rejected():
    undeclared = HoldingsSnapshot(
        snapshot_id="snap-empty",
        as_of="2026-01-02T15:00:00Z",
        currency="USD",
        cash=Decimal("1000"),
        positions={},
        flat_declared=False,
    )
    context = make_context(holdings_snapshot=undeclared)
    verdict = validate_proposal(
        make_proposal(holdings_snapshot=undeclared.to_dict()), context=context
    )
    assert verdict.accepted is False
    assert verdict.reason_code is ReasonCode.UNDECLARED_FLAT


@pytest.mark.unit
def test_missing_candidate_snapshot_is_rejected():
    assert_rejected(ReasonCode.MISSING_HOLDINGS_SNAPSHOT, holdings_snapshot=None)


@pytest.mark.unit
def test_missing_trusted_snapshot_is_not_defaulted_to_flat():
    verdict = validate_proposal(make_proposal(), context=make_context(holdings_snapshot=None))
    assert verdict.accepted is False
    assert verdict.reason_code is ReasonCode.UNRESOLVED_HOLDINGS_SNAPSHOT


@pytest.mark.unit
def test_forged_snapshot_contents_are_rejected():
    forged = {
        "snapshot_id": "snap-001",
        "as_of": "2026-01-02T15:00:00Z",
        "currency": "USD",
        "cash": "999999",
        "positions": {"AAPL": "5"},
        "flat_declared": False,
    }
    verdict = assert_rejected(ReasonCode.HOLDINGS_SNAPSHOT_MISMATCH, holdings_snapshot=forged)
    # The verdict must report the trusted source, never the forged candidate.
    assert verdict.snapshot_id == "snap-001"


@pytest.mark.unit
def test_candidate_snapshot_reference_by_id_is_accepted():
    verdict = verdict_for(holdings_snapshot="snap-001")
    assert verdict.accepted is True
    assert verdict.snapshot_id == "snap-001"


@pytest.mark.unit
def test_buy_exceeding_trusted_cash_is_rejected():
    # 11 * 100 = 1100 > trusted cash 1000.
    assert_rejected(ReasonCode.INSUFFICIENT_CASH, units=11)


@pytest.mark.unit
def test_sell_exceeding_trusted_holdings_is_rejected():
    # Trusted position is 5.
    assert_rejected(ReasonCode.INSUFFICIENT_HOLDINGS, action="sell", units=6)


@pytest.mark.unit
@pytest.mark.parametrize("action", ["buy", "sell"])
def test_zero_units_on_buy_or_sell_is_rejected(action):
    assert_rejected(ReasonCode.NON_POSITIVE_UNITS, action=action, units=0)


@pytest.mark.unit
@pytest.mark.parametrize("action", ["buy", "sell"])
def test_negative_units_are_rejected_under_long_only_policy(action):
    assert_rejected(ReasonCode.NEGATIVE_UNITS, action=action, units=-1)


@pytest.mark.unit
def test_negative_holdings_are_rejected():
    negative = HoldingsSnapshot(
        snapshot_id="snap-negative",
        as_of="2026-01-02T15:00:00Z",
        currency="USD",
        cash=Decimal("1000"),
        positions={"AAPL": Decimal("-1")},
        flat_declared=False,
    )
    context = make_context(holdings_snapshot=negative)
    verdict = validate_proposal(
        make_proposal(holdings_snapshot=negative.to_dict()), context=context
    )
    assert verdict.accepted is False
    assert verdict.reason_code is ReasonCode.NEGATIVE_HOLDINGS


@pytest.mark.unit
def test_negative_trusted_cash_is_rejected():
    negative = HoldingsSnapshot(
        snapshot_id="snap-negative-cash",
        as_of="2026-01-02T15:00:00Z",
        currency="USD",
        cash=Decimal("-1"),
        positions={"AAPL": Decimal("5")},
        flat_declared=False,
    )
    context = make_context(holdings_snapshot=negative)
    verdict = validate_proposal(
        make_proposal(holdings_snapshot=negative.to_dict()), context=context
    )
    assert verdict.accepted is False
    assert verdict.reason_code is ReasonCode.INVALID_CASH


@pytest.mark.unit
@pytest.mark.parametrize("price", [0, "-1", Decimal("-0.01")])
def test_non_positive_price_is_rejected(price):
    assert_rejected(ReasonCode.NON_POSITIVE_PRICE, price=price)


@pytest.mark.unit
@pytest.mark.parametrize(
    "price",
    [float("nan"), float("inf"), float("-inf"), Decimal("NaN"), Decimal("Infinity"), "NaN"],
)
def test_non_finite_price_is_rejected(price):
    assert_rejected(ReasonCode.NON_FINITE_PRICE, price=price)


@pytest.mark.unit
def test_unparseable_price_is_rejected():
    assert_rejected(ReasonCode.INVALID_PRICE, price="not-a-number")


@pytest.mark.unit
def test_currency_mismatch_is_rejected():
    assert_rejected(ReasonCode.CURRENCY_MISMATCH, currency="EUR")


@pytest.mark.unit
def test_trusted_snapshot_currency_mismatch_is_rejected():
    eur = HoldingsSnapshot(
        snapshot_id="snap-eur",
        as_of="2026-01-02T15:00:00Z",
        currency="EUR",
        cash=Decimal("1000"),
        positions={"AAPL": Decimal("5")},
        flat_declared=False,
    )
    context = make_context(holdings_snapshot=eur)
    verdict = validate_proposal(make_proposal(holdings_snapshot=eur.to_dict()), context=context)
    assert verdict.accepted is False
    assert verdict.reason_code is ReasonCode.CURRENCY_MISMATCH


@pytest.mark.unit
def test_missing_rule_version_is_rejected():
    assert_rejected(ReasonCode.MISSING_RULE_VERSION, rule_version=None)


@pytest.mark.unit
def test_unknown_rule_version_is_rejected():
    assert_rejected(ReasonCode.UNKNOWN_RULE_VERSION, rule_version="v9")


@pytest.mark.unit
def test_rule_version_mismatch_is_rejected():
    context = make_context(
        rule_set=RuleSet(version="v1"),
        available_rule_versions=frozenset({"v1", "v2"}),
    )
    verdict = validate_proposal(make_proposal(rule_version="v2"), context=context)
    assert verdict.accepted is False
    assert verdict.reason_code is ReasonCode.RULE_VERSION_MISMATCH


@pytest.mark.unit
def test_missing_trusted_rule_set_is_rejected():
    context = make_context(rule_set=None, available_rule_versions=frozenset({"v1"}))
    verdict = validate_proposal(make_proposal(rule_version="v1"), context=context)
    assert verdict.accepted is False
    assert verdict.reason_code is ReasonCode.UNKNOWN_RULE_VERSION


@pytest.mark.unit
@pytest.mark.parametrize(
    "overrides",
    [
        {"action": "execute"},
        {"action": "place_order"},
        {"status": "execute"},
        {"execution_mode": "live"},
        {"execution_mode": "broker"},
        {"real_execution": True},
        {"live": True},
        {"broker_order_id": "order-1"},
    ],
)
def test_real_execution_requests_are_permanently_rejected(overrides):
    verdict = assert_rejected(ReasonCode.REAL_EXECUTION_REQUESTED, **overrides)
    assert verdict.accepted is False


@pytest.mark.unit
def test_llm_self_reported_safety_cannot_override_failed_rules():
    verdict = assert_rejected(
        ReasonCode.INSUFFICIENT_CASH,
        units=11,
        status="accepted",
        safe=True,
        approved=True,
        authorized=True,
    )
    assert verdict.status is ProposalStatus.REJECTED
    assert {"status", "safe", "approved", "authorized"} <= set(verdict.ignored_claims)


@pytest.mark.unit
def test_llm_self_reported_safety_does_not_replace_code_verdict_on_accept():
    verdict = verdict_for(units=2, status="accepted", safe=True)
    assert verdict.accepted is True
    assert verdict.reason_code is ReasonCode.ACCEPTED
    assert "safe" in verdict.ignored_claims
    assert "status" in verdict.ignored_claims


@pytest.mark.unit
def test_missing_required_fields_have_stable_reason_codes():
    assert_rejected(ReasonCode.MISSING_ACTION, action=None)
    assert_rejected(ReasonCode.MISSING_UNITS, units=None)
    assert_rejected(ReasonCode.MISSING_PRICE, price=None)
    assert_rejected(ReasonCode.MISSING_CURRENCY, currency=None)


@pytest.mark.unit
def test_unknown_action_is_rejected_without_treating_it_as_buy():
    assert_rejected(ReasonCode.UNSUPPORTED_ACTION, action="short")


@pytest.mark.unit
def test_malformed_proposal_is_rejected():
    verdict = validate_proposal("not-a-proposal", context=make_context())
    assert verdict.accepted is False
    assert verdict.reason_code is ReasonCode.INVALID_PROPOSAL


@pytest.mark.unit
def test_decimal_amounts_avoid_binary_float_boundary_errors():
    # 3 * 0.1 is exactly 0.3 in decimal arithmetic, but not in binary floats.
    account = HoldingsSnapshot(
        snapshot_id="snap-decimal",
        as_of="2026-01-02T15:00:00Z",
        currency="USD",
        cash=Decimal("0.30"),
        positions={},
        flat_declared=True,
    )
    context = make_context(holdings_snapshot=account)

    accepted = validate_proposal(
        make_proposal(units=3, price=0.1, holdings_snapshot=account.to_dict()),
        context=context,
    )
    assert accepted.accepted is True

    rejected = validate_proposal(
        make_proposal(units=4, price=0.1, holdings_snapshot=account.to_dict()),
        context=context,
    )
    assert rejected.accepted is False
    assert rejected.reason_code is ReasonCode.INSUFFICIENT_CASH


@pytest.mark.unit
def test_replay_is_deterministic_and_does_not_mutate_input():
    proposal = make_proposal(units=11)
    context = make_context()
    before = dict(proposal)

    first = validate_proposal(proposal, context=context)
    second = validate_proposal(proposal, context=context)

    assert first == second
    assert first.to_dict() == second.to_dict()
    assert proposal == before


@pytest.mark.unit
def test_reason_codes_are_stable_strings():
    assert ReasonCode.ACCEPTED.value == "accepted"
    assert ReasonCode.MISSING_HOLDINGS_SNAPSHOT.value == "missing_holdings_snapshot"
    assert ReasonCode.INSUFFICIENT_CASH.value == "insufficient_cash"
    assert ReasonCode.REAL_EXECUTION_REQUESTED.value == "real_execution_requested"


@pytest.mark.unit
def test_action_enum_only_contains_simulation_actions():
    assert {action.value for action in Action} == {"buy", "sell", "hold"}

"""Deterministic validation of simulation proposals (FR-003, INV-003, SEC-001).

The validator is the authoritative gate. Candidate-provided status, safety text,
balance, holdings or rule version are never trusted. The caller supplies a
``SafetyContext`` built from independent sources: the trusted account snapshot,
the trusted rule catalog and the instrument quote currency. The verdict is a
pure function of those inputs, so the same proposal/snapshot/rule version
replays identically (NFR-003).

Out of scope this session (do not invent): reference-price deviation limits,
fees and extra position caps. They are pending policy inputs.

No broker, network or credential access is performed here.
"""
from __future__ import annotations

from collections.abc import Mapping
from decimal import Decimal
from typing import Any

from .models import (
    Action,
    HoldingsSnapshot,
    ProposalStatus,
    ReasonCode,
    SafetyContext,
    SafetyVerdict,
    SimulationProposal,
    parse_decimal,
    parse_holdings_snapshot,
)

REAL_EXECUTION_ACTIONS = frozenset(
    {
        "execute",
        "executed",
        "place_order",
        "submit_order",
        "real_order",
        "live_order",
        "broker_order",
    }
)
REAL_EXECUTION_MODES = frozenset({"live", "real", "broker", "production", "execute"})
REAL_EXECUTION_FLAGS = (
    "real_execution",
    "live",
    "live_trading",
    "submit_order",
    "place_order",
    "execute_now",
    "broker",
    "broker_order",
    "broker_order_id",
)
SELF_AUTHORIZATION_KEYS = (
    "status",
    "safe",
    "is_safe",
    "approved",
    "authorized",
    "authorization",
    "verdict",
    "safety_verdict",
)


def _string_or_none(value: Any) -> str | None:
    if isinstance(value, str) and value.strip():
        return value.strip()
    return None


def _trusted_rule_version(context: SafetyContext | None) -> str | None:
    if isinstance(context, SafetyContext) and context.rule_set is not None:
        return context.rule_set.version
    return None


def _trusted_snapshot_id(context: SafetyContext | None) -> str | None:
    if not isinstance(context, SafetyContext):
        return None
    snapshot = context.holdings_snapshot
    if isinstance(snapshot, HoldingsSnapshot):
        return snapshot.snapshot_id
    if isinstance(snapshot, Mapping):
        raw = snapshot.get("snapshot_id")
        if isinstance(raw, str) and raw.strip():
            return raw.strip()
    return None


def _reject(
    reason: ReasonCode,
    message: str,
    candidate: SimulationProposal | None = None,
    context: SafetyContext | None = None,
    ignored: tuple[str, ...] = (),
) -> SafetyVerdict:
    return SafetyVerdict(
        accepted=False,
        reason_code=reason,
        message=message,
        status=ProposalStatus.REJECTED,
        action=_string_or_none(getattr(candidate, "action", None)),
        rule_version=_trusted_rule_version(context),
        snapshot_id=_trusted_snapshot_id(context),
        instrument=context.instrument if isinstance(context, SafetyContext) else None,
        is_noop=False,
        ignored_claims=ignored,
    )


def _accept(
    candidate: SimulationProposal,
    context: SafetyContext,
    action: Action,
    ignored: tuple[str, ...],
) -> SafetyVerdict:
    return SafetyVerdict(
        accepted=True,
        reason_code=ReasonCode.ACCEPTED,
        message="proposal accepted by deterministic safety rules",
        status=ProposalStatus.ACCEPTED,
        action=action.value,
        rule_version=_trusted_rule_version(context),
        snapshot_id=_trusted_snapshot_id(context),
        instrument=context.instrument,
        is_noop=action is Action.HOLD,
        ignored_claims=ignored,
    )


def _ignored_claims(candidate: SimulationProposal) -> tuple[str, ...]:
    claims: set[str] = set()
    if candidate.status is not None:
        claims.add("status")
    for key in SELF_AUTHORIZATION_KEYS:
        if key != "status" and key in candidate.extra:
            claims.add(key)
    return tuple(sorted(claims))


def _is_real_execution(candidate: SimulationProposal) -> bool:
    action = _string_or_none(candidate.action)
    if action is not None and action.lower() in REAL_EXECUTION_ACTIONS:
        return True

    status = _string_or_none(candidate.status)
    if status is not None and status.lower() in REAL_EXECUTION_ACTIONS:
        return True

    extra = candidate.extra
    mode = extra.get("execution_mode")
    if isinstance(mode, str) and mode.strip().lower() in REAL_EXECUTION_MODES:
        return True

    for key in REAL_EXECUTION_FLAGS:
        if key in extra and extra[key] not in (None, False, "", 0):
            return True
    return False


def _resolve_trusted_snapshot(
    context: SafetyContext,
) -> tuple[HoldingsSnapshot | None, ReasonCode | None]:
    trusted = context.holdings_snapshot
    if trusted is None:
        return None, ReasonCode.UNRESOLVED_HOLDINGS_SNAPSHOT
    if isinstance(trusted, HoldingsSnapshot):
        return trusted, None
    parsed, error = parse_holdings_snapshot(trusted)
    if parsed is None:
        return None, ReasonCode.UNRESOLVED_HOLDINGS_SNAPSHOT
    return parsed, error


def _check_candidate_snapshot(
    candidate: SimulationProposal,
    trusted: HoldingsSnapshot,
) -> ReasonCode | None:
    reference = candidate.holdings_snapshot
    if reference is None:
        return ReasonCode.MISSING_HOLDINGS_SNAPSHOT
    if isinstance(reference, str):
        if reference.strip() != trusted.snapshot_id:
            return ReasonCode.HOLDINGS_SNAPSHOT_MISMATCH
        return None
    if not isinstance(reference, Mapping) and not isinstance(reference, HoldingsSnapshot):
        return ReasonCode.INVALID_HOLDINGS_SNAPSHOT_REFERENCE
    parsed, error = parse_holdings_snapshot(reference)
    if parsed is None:
        return error or ReasonCode.INVALID_HOLDINGS_SNAPSHOT
    if not parsed.is_same_as(trusted):
        return ReasonCode.HOLDINGS_SNAPSHOT_MISMATCH
    return None


def _validate(candidate: SimulationProposal, context: SafetyContext) -> SafetyVerdict:
    ignored = _ignored_claims(candidate)

    # SEC-001: real execution is permanently rejected, before any other field.
    if _is_real_execution(candidate):
        return _reject(
            ReasonCode.REAL_EXECUTION_REQUESTED,
            "real broker execution is permanently rejected",
            candidate,
            context,
            ignored,
        )

    if candidate.action is None or (
        isinstance(candidate.action, str) and not candidate.action.strip()
    ):
        return _reject(ReasonCode.MISSING_ACTION, "missing action", candidate, context, ignored)
    action = Action.parse(candidate.action)
    if action is None:
        return _reject(
            ReasonCode.UNSUPPORTED_ACTION,
            "unsupported action; only buy/sell/hold are simulated",
            candidate,
            context,
            ignored,
        )

    if candidate.units is None:
        return _reject(ReasonCode.MISSING_UNITS, "missing units", candidate, context, ignored)
    units, _ = parse_decimal(candidate.units)
    if units is None:
        return _reject(
            ReasonCode.INVALID_UNITS,
            "units must be a finite number",
            candidate,
            context,
            ignored,
        )
    if units < 0:
        return _reject(
            ReasonCode.NEGATIVE_UNITS,
            "negative units are outside the explicit long-only policy",
            candidate,
            context,
            ignored,
        )
    if action is Action.HOLD:
        if units != 0:
            return _reject(
                ReasonCode.HOLD_UNITS_NOT_ZERO,
                "hold requires units == 0",
                candidate,
                context,
                ignored,
            )
    elif units == 0:
        return _reject(
            ReasonCode.NON_POSITIVE_UNITS,
            "buy/sell requires units > 0",
            candidate,
            context,
            ignored,
        )

    if candidate.price is None:
        return _reject(ReasonCode.MISSING_PRICE, "missing price", candidate, context, ignored)
    price, price_error = parse_decimal(candidate.price)
    if price is None:
        if price_error == "non_finite":
            return _reject(
                ReasonCode.NON_FINITE_PRICE,
                "price must be finite",
                candidate,
                context,
                ignored,
            )
        return _reject(
            ReasonCode.INVALID_PRICE,
            "price must be numeric",
            candidate,
            context,
            ignored,
        )
    if price <= 0:
        return _reject(
            ReasonCode.NON_POSITIVE_PRICE,
            "price must be greater than zero",
            candidate,
            context,
            ignored,
        )

    if candidate.currency is None or (
        isinstance(candidate.currency, str) and not candidate.currency.strip()
    ):
        return _reject(ReasonCode.MISSING_CURRENCY, "missing currency", candidate, context, ignored)
    if not isinstance(candidate.currency, str):
        return _reject(
            ReasonCode.INVALID_CURRENCY,
            "currency must be a string",
            candidate,
            context,
            ignored,
        )
    if candidate.currency.strip().upper() != context.instrument_currency.strip().upper():
        return _reject(
            ReasonCode.CURRENCY_MISMATCH,
            "candidate currency does not match the instrument quote currency",
            candidate,
            context,
            ignored,
        )

    trusted, snapshot_error = _resolve_trusted_snapshot(context)
    if trusted is None:
        return _reject(
            snapshot_error or ReasonCode.UNRESOLVED_HOLDINGS_SNAPSHOT,
            "trusted holdings snapshot is unavailable or invalid",
            candidate,
            context,
            ignored,
        )

    candidate_snapshot_error = _check_candidate_snapshot(candidate, trusted)
    if candidate_snapshot_error is not None:
        return _reject(
            candidate_snapshot_error,
            "candidate holdings snapshot is missing, malformed or not the trusted snapshot",
            candidate,
            context,
            ignored,
        )

    if trusted.currency.strip().upper() != context.instrument_currency.strip().upper():
        return _reject(
            ReasonCode.CURRENCY_MISMATCH,
            "trusted snapshot currency does not match the instrument quote currency",
            candidate,
            context,
            ignored,
        )
    if trusted.cash < 0:
        return _reject(
            ReasonCode.INVALID_CASH,
            "trusted cash must not be negative",
            candidate,
            context,
            ignored,
        )
    if any(quantity < 0 for quantity in trusted.positions.values()):
        return _reject(
            ReasonCode.NEGATIVE_HOLDINGS,
            "negative holdings are outside the explicit long-only policy",
            candidate,
            context,
            ignored,
        )
    if not trusted.positions and not trusted.flat_declared:
        return _reject(
            ReasonCode.UNDECLARED_FLAT,
            "empty holdings require an explicit flat declaration",
            candidate,
            context,
            ignored,
        )

    if candidate.rule_version is None or (
        isinstance(candidate.rule_version, str) and not candidate.rule_version.strip()
    ):
        return _reject(
            ReasonCode.MISSING_RULE_VERSION,
            "missing rule version",
            candidate,
            context,
            ignored,
        )
    if not isinstance(candidate.rule_version, str):
        return _reject(
            ReasonCode.UNKNOWN_RULE_VERSION,
            "rule version must be a string",
            candidate,
            context,
            ignored,
        )
    claimed_rule = candidate.rule_version.strip()
    trusted_rules = context.rule_set
    if trusted_rules is None:
        return _reject(
            ReasonCode.UNKNOWN_RULE_VERSION,
            "trusted rule set is unavailable",
            candidate,
            context,
            ignored,
        )
    if not trusted_rules.long_only:
        return _reject(
            ReasonCode.UNSUPPORTED_RULE_POLICY,
            "only the explicit long-only policy is implemented",
            candidate,
            context,
            ignored,
        )
    available = context.available_rule_versions or frozenset({trusted_rules.version})
    if claimed_rule not in available:
        return _reject(
            ReasonCode.UNKNOWN_RULE_VERSION,
            "candidate rule version is not in the trusted rule catalog",
            candidate,
            context,
            ignored,
        )
    if claimed_rule != trusted_rules.version:
        return _reject(
            ReasonCode.RULE_VERSION_MISMATCH,
            "candidate rule version does not match the pinned trusted rule version",
            candidate,
            context,
            ignored,
        )

    if action is Action.BUY:
        cost = units * price
        if cost > trusted.cash:
            return _reject(
                ReasonCode.INSUFFICIENT_CASH,
                "buy cost exceeds trusted cash",
                candidate,
                context,
                ignored,
            )
    elif action is Action.SELL:
        held = trusted.positions.get(context.instrument, Decimal("0"))
        if held < units:
            return _reject(
                ReasonCode.INSUFFICIENT_HOLDINGS,
                "sell units exceed trusted holdings",
                candidate,
                context,
                ignored,
            )

    return _accept(candidate, context, action, ignored)


def validate_proposal(proposal: Any, *, context: SafetyContext) -> SafetyVerdict:
    """Return a deterministic accept/reject verdict for a simulation proposal.

    ``proposal`` may be a ``SimulationProposal`` or a mapping with the fixed
    contract fields. ``context`` must contain the independently trusted snapshot
    and rule set. Any unexpected error fails closed with ``VALIDATION_ERROR``.
    """
    candidate: SimulationProposal | None = None
    try:
        if not isinstance(context, SafetyContext):
            return _reject(
                ReasonCode.VALIDATION_ERROR,
                "a trusted SafetyContext is required",
            )
        if isinstance(proposal, SimulationProposal):
            candidate = proposal
        elif isinstance(proposal, Mapping):
            candidate = SimulationProposal.from_mapping(proposal)
        else:
            return _reject(
                ReasonCode.INVALID_PROPOSAL,
                "proposal must be a mapping or SimulationProposal",
                None,
                context,
            )
        return _validate(candidate, context)
    except Exception:
        return _reject(
            ReasonCode.VALIDATION_ERROR,
            "unexpected validation failure; failing closed",
            candidate,
            context if isinstance(context, SafetyContext) else None,
        )

